#!/usr/bin/env python3
"""Независимо пересчитывает фиксированное окно по реальным callback timestamp; пропуски не превращает в0 FPS."""

from __future__ import annotations

import hashlib
import json
import math
from pathlib import Path
import re

from tools.common.paths import project_root
from tools.common.launch import prepare_imports

ROOT = project_root(__file__)
prepare_imports(ROOT)
PLAN = ROOT / "docs/reports/visual-overhaul/vfoliage-006/ci-performance/plan.json"
PREFIX = "PERF_CAPTURE "
ENGINE = "a13da4feb8d8aefc283c3763d33a2f170a18d541"
ANSI_ESCAPE = re.compile(
    r"(?:\x1b\[|\x9b)[0-?]*[ -/]*[@-~]|\x1b\][^\x07\x1b\r\n]*(?:\x07|\x1b\\)"
)


class MeasurementError(ValueError):
    """Отличает отсутствующее/повреждённое измерение от настоящего результата ниже бюджета."""


def digest(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def policy() -> dict:
    """Не позволяет незаметно сократить окно, убрать повтор или понизить бюджет."""
    data = json.loads(PLAN.read_text())
    wanted = {
        "minimum_fps": 50,
        "headless_cap_after_startup": 60,
        "warmup_usec": 3_000_000,
        "window_usec": 10_000_000,
        "sample_usec": 1_000_000,
        "minimum_valid_samples": 10,
        "repeats_per_mode": 3,
        "seed": 21101986,
        "locale": "ru",
        "engine_hash": ENGINE,
        "modes": ["normal", "f10"],
    }
    if any(data.get(key) != value for key, value in wanted.items()):
        raise MeasurementError("invalid fixed performance policy")
    return data


def events(raw: bytes, returncode: int) -> list[dict]:
    """Сначала проверяет результат процесса и ошибки, затем читает все записи без отбрасывания повреждённых."""
    if returncode != 0:
        raise MeasurementError("process_error: " + str(returncode))
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise MeasurementError("invalid_utf8") from exc
    # Нормализуем только копию для поиска ошибок; raw/SHA и строки протокола остаются исходными.
    error_text = "\n".join(
        line.lstrip() for line in ANSI_ESCAPE.sub("", text).splitlines()
    )
    if re.search(r"^ERROR:|SCRIPT ERROR:|Parse Error", error_text, re.M):
        raise MeasurementError("engine_error")
    rows = []

    def unique_pairs(pairs):
        result = {}
        for key, value in pairs:
            if key in result:
                raise ValueError("duplicate JSON key")
            result[key] = value
        return result

    try:
        for line in text.splitlines():
            if line.startswith(PREFIX):
                row = json.loads(
                    line.removeprefix(PREFIX), object_pairs_hook=unique_pairs
                )
                if not isinstance(row, dict) or "kind" not in row:
                    raise ValueError("object/kind required")
                rows.append(row)
    except (ValueError, TypeError) as exc:
        raise MeasurementError("invalid_protocol_record") from exc
    if not rows:
        raise MeasurementError("missing_measurements: no sampler records")
    return rows


def integer(value: object) -> int:
    if type(value) is not int or value < 0:
        raise MeasurementError("invalid_integer_timestamp_or_count")
    return value


def _validate(raw: bytes, returncode: int, mode: str, expected: dict) -> dict:
    """Все десять интервалов пересчитываются из timestamp; настоящие нулевые/медленные интервалы учитываются."""
    plan = policy()
    if set(expected) != {"sampler_sha256", "scene_sha256", "plan_sha256"}:
        raise MeasurementError("invalid_expected_identity_keys")
    if any(not re.fullmatch(r"[a-f0-9]{64}", value) for value in expected.values()):
        raise MeasurementError("invalid_expected_fingerprint")
    rows = events(raw, returncode)
    kinds = [r["kind"] for r in rows]
    if (
        kinds.count("ready") != 1
        or kinds.count("begin") != 1
        or kinds.count("end") != 1
    ):
        raise MeasurementError("missing_or_duplicate_window_markers")
    if any(k not in ["ready", "begin", "frame", "sample", "end"] for k in kinds):
        raise MeasurementError("unknown_record_or_sampler_error")
    ready, begin, end = rows[0], rows[1], rows[-1]
    if [ready["kind"], begin["kind"], end["kind"]] != ["ready", "begin", "end"]:
        raise MeasurementError("invalid_record_order")
    config = {
        "purpose": "fixed_window_headless_gate",
        "schema": 1,
        "mode": mode,
        "autoplay": True,
        "debug": mode == "f10",
        "cap_after": 60,
        "display": "headless",
        "engine_hash": ENGINE,
        "warmup_us": 3_000_000,
        "window_us": 10_000_000,
        "sample_us": 1_000_000,
        "minimum_samples": 10,
        "seed": plan["seed"],
        "locale": plan["locale"],
        **expected,
    }
    if mode not in plan["modes"] or any(
        ready.get(k) != v or type(ready.get(k)) is not type(v)
        for k, v in config.items()
    ):
        raise MeasurementError("effective_configuration_differs")
    if not re.fullmatch(r"Codex-Performance-[a-f0-9]{32}", ready.get("profile", "")):
        raise MeasurementError("invalid_isolated_profile")
    integer(ready["cap_before"])
    integer(ready["startup_us"])
    for key in ["player", "camera"]:
        if len(ready[key]) != 2 or any(
            type(value) not in [int, float] or not math.isfinite(value)
            for value in ready[key]
        ):
            raise MeasurementError("invalid_initial_route_coordinates")
    start = integer(begin["time_us"])
    if start - integer(ready["time_us"]) < plan["warmup_usec"]:
        raise MeasurementError("warmup_too_short")
    stop = start + plan["window_usec"]
    if integer(end["time_us"]) < stop or end["window_us"] != plan["window_usec"]:
        raise MeasurementError("window_too_short")
    frames = [r for r in rows if r["kind"] == "frame"]
    samples = [r for r in rows if r["kind"] == "sample"]
    if len(samples) != 10 or not frames:
        raise MeasurementError("missing_complete_samples_or_closing_callback")
    if kinds != ["ready", "begin"] + ["frame"] * len(frames) + ["sample"] * 10 + [
        "end"
    ]:
        raise MeasurementError("invalid_record_order")
    counts = [0] * 10
    last_time, last_frame, last_engine = start, integer(begin["frame"]), -1
    for frame in frames:
        now, number = integer(frame["time_us"]), integer(frame["frame"])
        engine_frame = integer(frame["engine_frame"])
        if now <= last_time or number != last_frame + 1 or engine_frame <= last_engine:
            raise MeasurementError("non_monotonic_or_missing_callbacks")
        if frame["cap"] != 60:
            raise MeasurementError("effective_cap_changed")
        if now < stop:
            counts[(now - start) // plan["sample_usec"]] += 1
        last_time, last_frame, last_engine = now, number, engine_frame
    if last_time != end["time_us"] or last_frame != end["frame"]:
        raise MeasurementError("closing_callback_differs")
    if any(frame["time_us"] >= stop for frame in frames[:-1]):
        raise MeasurementError("continued_after_closed_window")
    for index, sample in enumerate(samples):
        if (
            integer(sample["index"]) != index
            or integer(sample["start_us"]) != start + index * plan["sample_usec"]
            or integer(sample["duration_us"]) != plan["sample_usec"]
            or integer(sample["frames"]) != counts[index]
            or type(sample["fps"]) not in [int, float]
            or not math.isfinite(float(sample["fps"]))
            or sample["fps"] != counts[index]
        ):
            raise MeasurementError("sample_differs_from_real_callbacks")
    count = sum(counts)
    if integer(end["window_frames"]) != count:
        raise MeasurementError("total_differs_from_raw_callbacks")
    passed = count * 1_000_000 >= plan["minimum_fps"] * plan["window_usec"]
    return {
        "mode": mode,
        "valid": True,
        "budget_passed": passed,
        "status": "passed" if passed else "budget_exceeded",
        "average_fps": count * 1_000_000 / plan["window_usec"],
        "minimum_fps": plan["minimum_fps"],
        "samples": counts,
        "window_us": plan["window_usec"],
        "actual_close_us": end["time_us"] - start,
        "window_frames": count,
        "profile": ready["profile"],
        "cap_before": ready["cap_before"],
        "cap_after": ready["cap_after"],
        "startup_us": ready["startup_us"],
    }


def validate(raw: bytes, returncode: int, mode: str, expected: dict) -> dict:
    """Любая утрата полей или неверный тип имеет явный invalid-результат, а не вычисленный FPS."""
    try:
        return _validate(raw, returncode, mode, expected)
    except MeasurementError:
        raise
    except (KeyError, TypeError, ValueError, IndexError) as exc:
        raise MeasurementError("invalid_measurement_fields: " + str(exc)) from exc

changes.tools/qa/performance/redraw_frame_review:
extends SceneTree

var game: Node2D
var review_output := ""
var review_mode := "normal"
var review_probe := "res://tests/helpers/redraw_frame_probe.gd"
var passed := 0
var failed := 0
var phases: Array = []
var review_presented := 0


## Выбирает режим и новый изолированный профиль; существующий output отклоняется до записи.
func _initialize() -> void:
	for arg in OS.get_cmdline_user_args():
		if arg.begins_with("--redraw-output="):
			review_output = arg.trim_prefix("--redraw-output=")
		elif arg.begins_with("--redraw-mode="):
			review_mode = arg.trim_prefix("--redraw-mode=")
		elif arg.begins_with("--redraw-probe="):
			review_probe = arg.trim_prefix("--redraw-probe=")
	var profile := "Codex-Redraw-" + str(OS.get_process_id()) + "-" + str(Time.get_ticks_usec())
	if review_output.is_empty() and OS.has_environment("FARM_REDRAW_TEST_OUTPUT"):
		review_output = OS.get_environment("FARM_REDRAW_TEST_OUTPUT").path_join(review_mode)
	ProjectSettings.set_setting("application/config/use_custom_user_dir", true)
	ProjectSettings.set_setting("application/config/custom_user_dir_name", profile)
	if (
		DirAccess.dir_exists_absolute(OS.get_user_data_dir())
		or review_mode not in ["normal", "f10"]
	):
		push_error("fresh isolated redraw profile/mode required")
		quit(2)
		return
	if not review_output.is_empty():
		if DirAccess.dir_exists_absolute(review_output):
			push_error("fresh redraw output required")
			quit(2)
			return
		DirAccess.make_dir_recursive_absolute(review_output)
	_run.call_deferred()


func check(condition: bool, message: String) -> void:
	if condition:
		passed += 1
	else:
		failed += 1
		print("REDRAW_FAIL ", message)


## Запускает настоящую main при cap10, вынуждая physics60/max8 пройти catch-up перед draw.
func _run() -> void:
	RenderingServer.frame_post_draw.connect(_review_presented_frame)
	seed(21101986)
	game = load("res://main.tscn").instantiate()
	game.set_script(load(review_probe))  # Before entering the tree: no live-node state reset.
	game.world_loot_seed = 21101986
	root.add_child(game)
	game.LocaleSystem.set_locale("ru", false)
	game.settings_state.pause_on_focus_loss = false  # Isolated QA profile; no user settings written.
	Engine.max_fps = 10
	if DisplayServer.get_name() != "headless":
		root.grab_focus()
	check(game.has_node("WorldBackground"), "actual main retains WorldBackground")
	check(game.benchmark_autoplay, "actual autoplay startup")
	check(game.DebugOverlaySystem.active(game) == (review_mode == "f10"), "actual F10 startup mode")
	for index in 6:
		await process_frame
	for specification in [
		["world", 8], ["pause", 6], ["inventory", 6], ["editor", 6], ["resumed", 8]
	]:
		await phase(String(specification[0]), int(specification[1]))
	var records := PackedStringArray()
	for key in game.review_process:
		var encoded := JSON.stringify(
			{
				"process": game.review_process[key],
				"physics": game.review_physics.get(key, {}),
				"draws": game.review_draw.get(key, 0),
				"draw_ui": game.review_draw_state.get(key, [])
			}
		)
		print("REDRAW_FRAME ", encoded)
		records.append(encoded)
	var summary := {
		"mode": review_mode,
		"passed": passed,
		"failed": failed,
		"phases": phases,
		"profile": OS.get_user_data_dir().get_file(),
		"display": DisplayServer.get_name(),
		"engine": Engine.get_version_info(),
		"cap": Engine.max_fps,
		"physics_hz": Engine.physics_ticks_per_second,
		"max_catchup": Engine.max_physics_steps_per_frame,
		"purpose": "functional_catchup_and_latest_UI_not_FPS_admission"
	}
	print("REDRAW_SUMMARY ", JSON.stringify(summary))
	if not review_output.is_empty():
		var raw_file := FileAccess.open(review_output.path_join("frames.jsonl"), FileAccess.WRITE)
		raw_file.store_string("\n".join(records) + "\n")
		var file := FileAccess.open(review_output.path_join("summary.json"), FileAccess.WRITE)
		file.store_string(JSON.stringify(summary, "  ") + "\n")
	print("REDRAW: %d passed, %d failed" % [passed, failed])
	quit(0 if failed == 0 else 1)


## Сохраняет переходные кадры, исключая первые два только из steady-проверок;
## нативный снимок требует свежую фазу после реального present, отдельно от CPU callback.
func phase(label: String, count: int) -> void:
	game.menu_state.pause_open = false
	game.inventory_open = false
	if game.LevelEditorSystem.active(game):
		game.LevelEditorSystem.toggle(game)
	if review_mode == "f10" and not game.DebugOverlaySystem.active(game):
		game.DebugOverlaySystem.toggle(game)
	if label == "pause":
		game.menu_state.pause_open = true
	elif label == "inventory":
		game.inventory_open = true
	elif label == "editor":
		game.LevelEditorSystem.toggle(game)
	game.review_phase = label
	var first := Engine.get_process_frames()
	var minute_before: float = game.game_minutes
	for index in count:
		await process_frame
	var last := Engine.get_process_frames()
	var frames := 0
	var physics := 0
	var draws := 0
	for key in game.review_process:
		# All raw frames are retained. Exclude the first two transition frames from steady-phase assertions.
		if key < first + 2 or key >= last:
			continue
		frames += 1
		var rendered := int(game.review_draw.get(key, 0))
		var updates: Dictionary = game.review_physics.get(key, {"count": 0, "delta_sum": 0.0})
		physics += int(updates.count)
		draws += rendered
		check(rendered == 1, label + ": one draw after all catch-up steps, frame" + str(key))
		check(
			game.review_draw_state.get(key, []) == game.review_process[key].ui,
			label + ": last process UI is rendered"
		)
		check(
			absf(float(updates.delta_sum) - float(updates.count) / 60.0) < 0.000001,
			label + ": physics deltas retained"
		)
	check(frames >= 3, label + ": complete observed frames")
	check(physics > frames * 2, label + ": actual multi-step physics catch-up")
	var advances := float(game.game_minutes) > minute_before
	check(
		advances if label in ["world", "resumed"] else not advances,
		label + ": simulation advances/freezes as intended"
	)
	var result := {
		"label": label,
		"first_frame": first,
		"end_frame_exclusive": last,
		"steady_frames": frames,
		"physics_calls": physics,
		"draws": draws,
		"minute_before": minute_before,
		"minute_after": game.game_minutes
	}
	if DisplayServer.get_name() != "headless" and not review_output.is_empty():
		root.grab_focus()
		var before_present := Engine.get_frames_drawn()
		var before_signal := review_presented
		var deadline := Time.get_ticks_usec() + 5000000
		print("REDRAW_CAPTURE_WAIT ", JSON.stringify({"phase":label,"drawn":before_present,
			"post_draw_signals":before_signal,"window_visible":root.visible,"window_focused":root.has_focus()}))
		while review_presented < before_signal + 2 and Time.get_ticks_usec() < deadline:
			await process_frame
		var image := root.get_texture().get_image()
		check(not image.is_empty(), label + ": real native framebuffer")
		if not image.is_empty():
			var path := review_output.path_join(label + ".png")
			check(image.save_png(path) == OK, label + ": native PNG saved")
			result["image_size"] = [image.get_width(), image.get_height()]
			var expected_color: Color = game.review_marker_color()
			var fresh := false
			for y in mini(64, image.get_height()):
				if image.get_pixel(mini(16, image.get_width() - 1), y).is_equal_approx(expected_color):
					fresh = true
			check(fresh, label + ": framebuffer contains current draw phase marker")
			result["phase_marker_fresh"] = fresh
			result["frames_drawn_before"] = before_present
			result["frames_drawn_after"] = Engine.get_frames_drawn()
			result["window_focused"] = root.has_focus()
			result["window_visible"] = root.visible
			result["present_wait_complete"] = review_presented >= before_signal + 2
	phases.append(result)


## Считает реальные сигналы завершения обновления viewport, отдельно от CPU callbacks.
func _review_presented_frame() -> void:
	review_presented += 1

changes.tools/qa/performance/runtime_cleanup_rev:
extends SceneTree

const Game := preload("res://scripts/game.gd")
const Matte := preload("res://scripts/systems/sprite_matte_system.gd")
const Bounds := preload("res://scripts/systems/wildlife_visual_system.gd")
const Picker := preload("res://scripts/systems/level_editor_atlas_picker_renderer.gd")
const Cabinet := preload("res://scripts/systems/dev_cabinet_system.gd")
const MAINTENANCE := "res://scripts/systems/runtime_maintenance_system.gd"
var game: Node
var outputs: Array[WeakRef] = []
var cleanup_times: Array[int] = []

## Измеряет удержание временных ресурсов на одинаковой синтетической нагрузке до и после исправления.
func _initialize() -> void:
	ProjectSettings.set_setting("application/config/use_custom_user_dir",true)
	ProjectSettings.set_setting("application/config/custom_user_dir_name","Codex-Runtime-Cleanup-Review")
	_run.call_deferred()

## Сохраняет движковые счётчики и объём кешей, не называя ускоренную нагрузку длительной игровой сессией.
func _run() -> void:
	game=Game.new(); game._ready(); game.title_screen=false; game.language_screen=false
	game.current_location="cottage_interior"; game.player=Cabinet.POSITION
	var phase := "after" if FileAccess.file_exists(MAINTENANCE) else "before"
	var report := {"phase":phase,"protocol":"synthetic resource churn, headless; not real-time soak or FPS measurement","samples":[]}
	report.samples.append(snapshot(0))
	for batch in 8:
		churn(batch,250)
		if phase=="after":
			var maintenance=load(MAINTENANCE); maintenance.request(game)
			while maintenance.busy(game):
				var started := Time.get_ticks_usec(); maintenance.update(game)
				cleanup_times.append(Time.get_ticks_usec()-started)
				await process_frame
		await process_frame
		report.samples.append(snapshot((batch+1)*250))
	var live := 0
	for reference in outputs:
		if reference.get_ref()!=null: live+=1
	report.live_temporary_textures=live; report.temporary_textures=outputs.size()
	report.cleanup_usec=cleanup_times
	var folder := "res://docs/reports/runtime-cleanup-2026-10-15/"
	DirAccess.make_dir_recursive_absolute(folder)
	FileAccess.open(folder+phase+".json",FileAccess.WRITE).store_string(JSON.stringify(report,"\t")+"\n")
	print("RUNTIME CLEANUP REVIEW: ",phase," temporary textures still retained: ",live,"/",outputs.size())
	game.free(); quit()

## Создаёт и отпускает новые текстуры и запросы, повторяя путь редакторского предпросмотра и шкафа.
func churn(batch: int, count: int) -> void:
	for index in count:
		var source := Image.create(64,64,false,Image.FORMAT_RGBA8)
		source.fill(Color(0.3,0.6,0.8,1)); source.set_pixel(0,0,Color.MAGENTA)
		var owner := ImageTexture.create_from_image(source)
		var result: Texture2D=Matte.clean_texture(owner)
		Bounds.visible_bounds(result,Rect2i(0,0,64,64)); Picker.visible_preview_source(result,Rect2(0,0,64,64))
		outputs.append(weakref(result))
		var state := Cabinet.state(game); state.query="missing_%d_%d"%[batch,index]; Cabinet.items(game)

## Возвращает только компактные числовые данные, чтобы сам измеритель не удерживал игровые ресурсы.
func snapshot(created: int) -> Dictionary:
	return {"created":created,"static_bytes":Performance.get_monitor(Performance.MEMORY_STATIC),"resources":Performance.get_monitor(Performance.OBJECT_RESOURCE_COUNT),"matte":Matte._textures.size(),"bounds":Bounds._bounds.size(),"picker":Picker._visible_source_cache.size(),"queries":Cabinet.state(game).cache.size()}

changes.tools/qa/performance/runtime_cleanup_soa:
extends SceneTree

const Scene := preload("res://main.tscn")
const Maintenance := preload("res://scripts/systems/runtime_maintenance_system.gd")
const Stone := preload("res://scripts/systems/qa_teleport_system.gd")
const Cabinet := preload("res://scripts/systems/dev_cabinet_system.gd")
const Matte := preload("res://scripts/systems/sprite_matte_system.gd")
const Bounds := preload("res://scripts/systems/wildlife_visual_system.gd")
const Picker := preload("res://scripts/systems/level_editor_atlas_picker_renderer.gd")
const FOLDER := "res://docs/reports/runtime-cleanup-2026-10-15/"
const MAX_FRAME_SAMPLES := 60_000
var game: Node2D
var viewport: SubViewport
var locations: Array
var failed := false

## Запускает настоящий оконный обход после прогрева без чтения слотов и вмешательства в обычную игру пользователя.
func _initialize() -> void:
	_start.call_deferred()

## Наблюдает реальные тридцатисекундные циклы обслуживания на повторяемом маршруте с малыми временными ресурсами.
func _start() -> void:
	if DisplayServer.get_name()=="headless": quit(2); return
	ProjectSettings.set_setting("application/config/use_custom_user_dir",true)
	ProjectSettings.set_setting("application/config/custom_user_dir_name","Codex-Runtime-Cleanup-Soak")
	DisplayServer.window_set_mode(DisplayServer.WINDOW_MODE_WINDOWED); root.size=Vector2i(1152,648)
	var container := SubViewportContainer.new(); root.add_child(container)
	viewport=SubViewport.new(); viewport.size=Vector2i(1152,648); viewport.render_target_update_mode=SubViewport.UPDATE_ALWAYS; container.add_child(viewport)
	game=Scene.instantiate(); game.set_meta("capture_windowed",true); viewport.add_child(game); current_scene=container
	game.set_process_input(false); game.set_process_unhandled_input(false)
	game.audio_enabled=false; game.language_screen=false; game.title_screen=false; game.tutorial_visible=false
	game.settings_state.pause_on_focus_loss=false
	game.FarmLifeSystem.state(game).first_day=6; game.FarmLifeSystem.state(game).cutscene=""; game.FarmLifeSystem.state(game).cutscene_timer=0
	game.state.player.profile.created=true; game.FirstChapterSystem.state(game).completed=true
	game.change_inventory_count(Stone.KIND,1); locations=Stone.locations(game)
	for index in locations.size()+2:
		set_case(index); await process_frame; await RenderingServer.frame_post_draw
	for frame in 120: await process_frame
	var duration := 180
	for arg in OS.get_cmdline_user_args():
		if arg.begins_with("--seconds="): duration=clampi(int(arg.get_slice("=",1)),60,7200)
	var started := Time.get_ticks_usec(); var previous := started; var next_sample := started
	var case_index := -1; var scanned := -1; var frames: Array[int]=[]; var slices: Array[int]=[]; var samples := []
	var created := 0; var rendered := 0
	while Time.get_ticks_usec()-started < duration*1_000_000 and not failed:
		await process_frame
		var now := Time.get_ticks_usec(); rendered+=1
		if frames.size()<MAX_FRAME_SAMPLES: frames.append(now-previous)
		previous=now
		var current: int = int((now-started)/3_000_000)
		if current!=case_index:
			case_index=current; set_case(current); churn(); created+=8
		game.menu_state.recovery_grace=5.0
		var state: Dictionary=game.get_meta(Maintenance.META,{})
		if int(state.get("scanned",0))!=scanned:
			scanned=int(state.get("scanned",0)); slices.append(int(state.get("last_usec",0)))
		if now>=next_sample:
			samples.append(snapshot((now-started)/1_000_000.0)); next_sample=now+10_000_000
			print("CLEANUP SOAK: ",int((now-started)/1_000_000),"s, cycles=",state.get("cycles",0))
	samples.append(snapshot((Time.get_ticks_usec()-started)/1_000_000.0))
	var report := {"pause_on_focus_loss":game.settings_state.pause_on_focus_loss,"protocol":"native fixed viewport; real-time periodic cleanup; warm route before sampling; intentional resource churn and transitions included in frame times","engine":Engine.get_version_info().string,"duration_seconds":(Time.get_ticks_usec()-started)/1_000_000.0,"window":[root.size.x,root.size.y],"viewport":[viewport.size.x,viewport.size.y],"adapter":RenderingServer.get_video_adapter_name(),"frames":rendered,"recorded_frame_limit":MAX_FRAME_SAMPLES,"frame_usec":frames,"cleanup_usec":slices,"temporary_created":created,"samples":samples,"failed":failed}
	DirAccess.make_dir_recursive_absolute(FOLDER)
	FileAccess.open(FOLDER+"native-soak.json",FileAccess.WRITE).store_string(JSON.stringify(report,"\t")+"\n")
	print("CLEANUP SOAK COMPLETE: ",report.duration_seconds,"s, ",rendered," frames")
	quit(1 if failed else 0)

## Чередует все карты, полный шкаф и рюкзак через настоящий QA-перенос, не подменяя боевые переходы.
func set_case(index: int) -> void:
	Stone.close(game); Cabinet.close(game); preload("res://scripts/systems/menu_hub_system.gd").close(game)
	var phase := index%(locations.size()+2)
	var target: String=locations[phase] if phase<locations.size() else "cottage_interior"
	if not Stone.open(game) or not Stone.travel(game,target): failed=true; push_error("Не выполнен переход стенда в "+target); return
	game.menu_state.recovery_grace=5.0
	if phase==locations.size(): game.player=Cabinet.POSITION; Cabinet.open(game)
	elif phase==locations.size()+1: game.open_inventory()
	game.update_camera()

## Имитирует небольшие временные предпросмотры, чьи исходники отпускаются после завершения вызова.
func churn() -> void:
	for index in 8:
